export const firstSetup=s=>s.settings.course?.firstSetup||{};
export function setupApparatus(s){const a=firstSetup(s),instrument=s.instruments.find(i=>i.id===a.instrumentId),column=s.columns.find(c=>c.id===a.columnId),model=s.columnModels.find(m=>m.id===column?.modelId);return {instrument,column,model,confirmed:!!a.confirmed&&!!instrument&&!!column&&!!model};}
const editSetup=(s,changes)=>{s.settings.course={...s.settings.course,firstSetup:{...firstSetup(s),...changes,confirmed:false}};};
const modelInUse=id=>Object.values(store.workspaces).some(s=>s.runs.some(r=>s.columns.find(c=>c.id===r.assoc.columnId?.value)?.modelId===id));
const instrumentInUse=id=>Object.values(store.workspaces).some(s=>s.runs.some(r=>r.assoc.instrumentId?.value===id));
export function chooseFirstInstrument(s,value){
 let id=value;
 if(value.startsWith('fleet:')){const ref=LOCAL_INSTRUMENT_FLEET.find(i=>i.fleetNumber===Number(value.slice(6)));if(!ref)return false;let i=s.instruments.find(i=>i.fleetNumber===ref.fleetNumber);if(!i){i=fromReferenceInstrument(ref);s.instruments.push(i);}id=i.id;}
 if(value==='other'){const i=newInstrument({label:'My instrument — configuration not yet recorded'});s.instruments.push(i);id=i.id;}
 if(id&&!s.instruments.some(i=>i.id===id))return false;editSetup(s,{instrumentId:id||null});return true;
}
export function chooseFirstColumn(s,value){
 let id=value;
 if(value==='teaching-start'){const m=newColumnModel({product:'Pinnacle starting column',beadFamily:'Pinnacle',particleType:'fully porous',lengthMm:150,idMm:4.6,particleUm:5,provenance:{source:'User-confirmed teaching starting geometry, 15 October 2026; not a product datasheet'},notes:'Editable starting setup. Ligand, model-specific ratings and current allocation are not inferred.'});s.columnModels.push(m);const c=newPhysicalColumn({modelId:m.id,label:'My starting column',notes:'Same user-selected column through Retention / Selectivity unless explicitly changed. Serial optional.'});s.columns.push(c);id=c.id;}
 if(value.startsWith('reference:')){const ref=REFERENCE_COLUMN_MODELS.find(m=>m.refId===value.slice(10));if(!ref)return false;let m=s.columnModels.find(m=>m.provenance?.source===`reference:${ref.refId}`);if(!m){m=fromReferenceColumnModel(ref);s.columnModels.push(m);}const c=newPhysicalColumn({modelId:m.id,label:'My '+ref.product+' column',notes:'Selected course product for a new user injection. Physical allocation requires user confirmation; serial is optional for website calculations.'});s.columns.push(c);id=c.id;}
 if(value==='other'){const m=newColumnModel({product:'My column — product/geometry not yet recorded'});s.columnModels.push(m);const c=newPhysicalColumn({modelId:m.id,label:'My column'});s.columns.push(c);id=c.id;}
 if(id&&!s.columns.some(c=>c.id===id))return false;editSetup(s,{columnId:id||null});return true;
}
export function confirmFirstApparatus(s){const a=setupApparatus(s);if(!a.instrument||!a.column||!a.model)return false;s.settings.course={...s.settings.course,firstSetup:{...firstSetup(s),confirmed:true}};return true;}
export function instrumentAlias(s,r){
 const a=setupApparatus(s),old=s.instruments.find(i=>i.id===r.assoc.instrumentId?.value);
 const number=i=>i?.fleetNumber||Number(/^HPLC\s*([1-6])$/i.exec(String(i?.identifier||i?.label||''))?.[1])||null;
 return a.confirmed&&old&&old.id!==a.instrument.id&&number(old)&&number(old)===number(a.instrument)?{old,selected:a.instrument}:null;
}
export function reconcileFirstInstrument(s,r){
 const alias=instrumentAlias(s,r);if(!alias)return false;
 r.assoc.instrumentId={value:alias.selected.id,confirmed:true,source:'user explicitly reconciled this CSV instrument descriptor with selected apparatus',previous:{...r.assoc.instrumentId},note:`Recorded ${alias.old.label}; selected ${alias.selected.label}. Original CSV and both instrument records retained.`};return true;
}
export function setupRunCheck(s,r){const a=setupApparatus(s);if(!a.confirmed)return {ok:false,reason:'Select and confirm your actual apparatus above first.'};
 for(const [key,value]of [['instrumentId',a.instrument.id],['columnId',a.column.id]])if(r.assoc[key]?.confirmed&&r.assoc[key].value!==value)return {ok:false,reason:'This CSV already has a different confirmed apparatus record. Keep it; use Equipment only if its original allocation needs correction.'};
 const p=r.profileExtras;
 if(p&&!profileConfirmationStatus(r).ok)return {ok:false,reason:'Resolve the CSV name-source conflict above before confirming its apparatus.'};
 if(p&&a.instrument.fleetNumber&&p.hplcNo!==a.instrument.fleetNumber)return {ok:false,reason:'The selected HPLC does not match this CSV’s recorded course-name HPLC. Do not attach future apparatus to an earlier injection.'};
 if(p){for(const key of ['lengthMm','idMm','particleUm'])if(Number.isFinite(p.geometry?.[key])&&Number.isFinite(a.model[key])&&p.geometry[key]!==a.model[key])return {ok:false,reason:'The selected column geometry differs from this CSV’s recorded geometry. Keep the original run separate.'};const code=decodeColumnCode(p.columnCode),phase=t=>{const v=String(t||'').toLowerCase().replace(/[^a-z0-9]/g,'');return /c18aq|aqueous|polarmodified|functionallybonded/.test(v)?'c18aq':/c18|octadecyl/.test(v)?'c18':/c8|octyl/.test(v)?'c8':/pfp|pentafluoro/.test(v)?'pfpp':/bip|diphen/.test(v)?'bip':/ibd|idb|embedded/.test(v)?'ibd':v;};if(code.ligand&&a.model.ligand&&phase(a.model.ligand)!==phase(code.ligand))return {ok:false,reason:'The selected column chemistry does not match this CSV’s recorded ligand. Review the original method; do not replace it with a future column.'};}
 if(p){const family=decodeColumnCode(p.columnCode).beadFamily,chosen=a.model.beadFamily||String(a.model.product||'').match(/Pinnacle|Ultra|Raptor|Force/i)?.[0];if(family&&chosen&&family.toLowerCase()!==chosen.toLowerCase())return {ok:false,reason:'The selected column product family differs from this CSV’s recorded family. Keep this injection’s original apparatus separate.'};}
 return {ok:true,reason:'Confirm only if this injection really used the selected instrument and this individual column. It does not confirm hardware ratings.'};
}
export function associateFirstApparatus(s,r){const z=setupRunCheck(s,r);if(!z.ok)return z;const a=setupApparatus(s);for(const [key,value]of [['instrumentId',a.instrument.id],['columnId',a.column.id]]){const old=r.assoc[key];r.assoc[key]={...old,value,confirmed:true,source:'user confirmed apparatus for this specific CSV; no historical serial required',...(old?.value&&old.value!==value?{previous:{...old}}:{})};}return z;}
export function recordMissingMethod(s,r,key,value){if(usable(r.conditions[key]))return false;
 const valid=key==='phaseA'?typeof value==='string'&&value.trim().length>0&&value.length<=500:key==='mode'?['ISO','GRA'].includes(value):key==='organic'?['ACN','MeOH','Mix'].includes(value):Number.isFinite(value)&&(key==='percentB'?value>=0&&value<=100:key==='mixAcnPct'?value>0&&value<100:key==='flow'?value>0:key==='ovenSetpoint'?value>=0&&value<=150:false);
 if(!valid)return false;r.conditions[key]=cond(value,'user',{unit:FIELD_BY_KEY[key]?.unit||'',note:'User recorded the actual method for this CSV, not a next-run draft or inferred history.'});return true;}

// Explicit prospective declaration, never retroactive: apply only to this import's
// new IDs, preserve file values and conflicts, and retain a per-run provenance note.
export function applyConfiguredImport(s,ids){
 const a=setupApparatus(s),cfg=firstSetup(s),acts=[];
 if(!cfg.applyToNewImports)return acts;
 for(const r of s.runs.filter(r=>ids.has(r.id))){
  const checked=setupRunCheck(s,r);
  const fileColumn=r.measured.fileMeta?.columnLabel,fileInstrument=r.measured.fileMeta?.instrumentLabel||r.measured.fileMeta?.instrumentName;
  const differentFileLabel=(fileColumn&&fileColumn!==a.column?.label)||(fileInstrument&&![a.instrument?.label,a.instrument?.identifier].includes(fileInstrument));
  if(!checked.ok||differentFileLabel){acts.push(`${r.label}: configured setup not applied: ${differentFileLabel?'CSV apparatus label differs from the prospective setup.':checked.reason}`);continue;}
  associateFirstApparatus(s,r);
  for(const [key,v]of Object.entries(cfg.method||{})){
   if(!FIELD_BY_KEY[key]||v===null||v===''||usable(r.conditions[key])||r.conditions[key]?.value!==null&&r.conditions[key]?.value!==undefined)continue;
   if(FIELD_BY_KEY[key].type==='number'&&!Number.isFinite(v)||key==='organic'&&!['ACN','MeOH','Mix'].includes(v)||key==='mode'&&!['ISO','GRA'].includes(v)||key==='mixAcnPct'&&!(v>0&&v<100))continue;
   if(key==='mixAcnPct'&&r.conditions.organic?.value!=='Mix')continue;
   if(['phaseB','mixAcnPct'].includes(key)&&cfg.method.organic&&r.conditions.organic?.value!==cfg.method.organic)continue;
   r.conditions[key]=cond(v,'user',{unit:FIELD_BY_KEY[key].unit,note:'Prospective setup declaration explicitly enabled before this CSV import. Applies to this new run only; file values and prior runs retained.'});
  }
  acts.push(`${r.label}: used the predeclared same-column setup for this newly imported run; original file values retained. Limits are not certified by this declaration.`);
 }
 return acts;
}

